// stored list was non-empty and whether a confirm was shown since the previous write.
function loadApp() {
  const elements = {};
  const log = { asks: 0, replaces: [] };
  let stored = [];
  let askedSinceWrite = false;
  const store = {
    readError: false,
    load() { return { todos: [], readError: false }; },
    save(todos) { stored = todos.slice(); askedSinceWrite = false; return 'saved'; },
    replace(todos) {
      log.replaces.push({ overNonEmpty: stored.length > 0, asked: askedSinceWrite });
      stored = todos.slice();
      askedSinceWrite = false;
      return 'saved';
    },
  };
  const document = {
    querySelector(sel) { return (elements[sel] ||= fakeElement()); },
    querySelectorAll() { return []; },
    createElement() { return fakeElement(); },
  };
  const dialog = document.querySelector('#confirm');
  dialog.addEventListener = (type, fn) => { dialog.onclose = fn; };
  dialog.showModal = () => {
    log.asks++;
    askedSinceWrite = true;
    dialog.returnValue = '';
    setImmediate(() => dialog.onclose());
  };
  vm.runInNewContext(appJs, { ...backup, store, document, crypto });
  const pick = (file) => {
    const input = document.querySelector('#import');
    input.files = [file];
    return input.onchange({ target: input });
  };
  const submit = (value) => {
    document.querySelector('#title').value = value;
    document.querySelector('#add').onsubmit({ preventDefault() {} });
  };
  return { pick, submit, log, stored: () => stored };
}

