  await flush();
  app.pick({ size: 10, text: async () => backupOf(['b1']) });
  await flush();
  big.finish();
  await flush();
  for (const r of app.log.replaces) assert.ok(!r.overNonEmpty || r.asked, 'replaced a non-empty list without asking');
  assert.equal(app.log.asks, 1);
  assert.equal(app.log.replaces.length, 1);
});

