// One import at a time: a file picked while another is still being read waits for it, so it sees (and asks about)
// the list that import left, instead of replacing it without asking.
let importing = Promise.resolve();

$('#import').onchange = (e) => {
  const input = e.target;
  const file = input.files[0];
  input.value = ''; // so the same file can be picked again
  if (!file) return;
  show(MESSAGES.reading);
  importing = importing.then(async () => {
    const current = todos;
    const result = await importBackup({ store, current, file, ask });
    if (result.todos !== current) todos = result.todos;
    show(result.message);
    render();
  });
  return importing;
};

